package com.bank.sbom;

import java.util.List;
import java.util.logging.Logger;

public class SbomIncidentQueryDemo {
    private static final Logger log = Logger.getLogger(SbomIncidentQueryDemo.class.getName());

    public static void main(String[] args) {
        log.info("Bank: National Bank of India — SBOM incident-response query (Log4Shell drill)");

        SbomIndex index = new SbomIndex();
        // Each service registers its resolved components (direct + transitive) at build time.
        index.register("payments-service", "2.4.1", List.of(
            new Component("org.apache.logging.log4j", "log4j-core", "2.14.1", true), // VULNERABLE
            new Component("org.springframework", "spring-web", "6.1.3", false)));
        index.register("transfer-service", "3.0.0", List.of(
            new Component("org.apache.logging.log4j", "log4j-core", "2.17.1", true), // patched
            new Component("org.postgresql", "postgresql", "42.7.1", false)));
        index.register("loan-service", "1.9.2", List.of(
            new Component("ch.qos.logback", "logback-classic", "1.4.14", true),      // not log4j
            new Component("org.hibernate", "hibernate-core", "6.4.1", false)));

        // Incident day: CVE announced for log4j-core < 2.15.0. Which services are affected?
        log.warning("CVE disclosed: log4j-core versions below 2.15.0 are vulnerable");
        List<String> affected = index.findAffected("org.apache.logging.log4j",
                "log4j-core", "2.15.0");

        if (affected.isEmpty()) {
            log.info("No services affected");
        } else {
            affected.forEach(a -> log.severe(() -> "AFFECTED → " + a + " (patch immediately)"));
        }
        log.info(() -> "Answered in one query across " + index.serviceCount()
                + " services — not days of manual grep");
    }
}

