package com.bank.sbom;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class SbomIndex {
    // service+version -> its component list (from the generated SBOM)
    private final Map<String, List<Component>> byService = new LinkedHashMap<>();

    void register(String service, String version, List<Component> components) {
        byService.put(service + "@" + version, components);
    }

    int serviceCount() { return byService.size(); }

    // The incident-day query: who uses group:name at a version BELOW the fixed one?
    List<String> findAffected(String group, String name, String fixedVersion) {
        List<String> affected = new ArrayList<>();
        for (Map.Entry<String, List<Component>> entry : byService.entrySet()) {
            for (Component c : entry.getValue()) {
                if (c.group().equals(group) && c.name().equals(name)
                        && isBelow(c.version(), fixedVersion)) {
                    affected.add(entry.getKey() + " uses " + name + " " + c.version()
                            + (c.transitive() ? " (transitive)" : " (direct)"));
                }
            }
        }
        return affected;
    }

    // Simple numeric version comparison for the demo (major.minor.patch).
    private boolean isBelow(String v, String fixed) {
        String[] a = v.split("\\."), b = fixed.split("\\.");
        for (int i = 0; i < Math.min(a.length, b.length); i++) {
            int x = Integer.parseInt(a[i]), y = Integer.parseInt(b[i]);
            if (x != y) return x < y;
        }
        return a.length < b.length;
    }
}
